import '../../domain/entities/explore_category.dart';
import '../../domain/entities/explore_metadata.dart';
import '../models/explore_content_model.dart';

List<ExploreContentModel> getFlagshipCityCatalog(String languageCode) {
  final locale = languageCode.trim().toLowerCase();
  return _items.map((item) => item.toModel(locale)).toList(growable: false);
}

class _FlagshipItem {
  const _FlagshipItem({required this.id, required this.countryCode, required this.countryName, required this.cityName, required this.category, required this.title, required this.latitude, required this.longitude, required this.coverImageUrl, required this.isFeatured});
  final String id, countryCode, countryName, cityName, title, coverImageUrl;
  final ExploreCategory category;
  final double latitude, longitude;
  final bool isFeatured;

  ExploreContentModel toModel(String locale) {
    final copy = _copy(locale, category.value, title, cityName);
    return ExploreContentModel(
      id: id, countryCode: countryCode, countryName: countryName, cityName: cityName, category: category, title: title,
      shortDescription: copy.$1, description: copy.$2, latitude: latitude, longitude: longitude,
      coverImageUrl: coverImageUrl, isFeatured: isFeatured,
      tags: <String>[category.value, cityName.toLowerCase(), countryCode.toLowerCase(), 'flagship_city'],
      metadata: ExploreMetadata(
        bestTime: category == ExploreCategory.place ? 'Morning or late afternoon' : 'Local peak time',
        localTip: copy.$3,
        estimatedVisitMinutes: category == ExploreCategory.place ? 90 : category == ExploreCategory.culture ? 60 : null,
        priceLevel: switch (category) { ExploreCategory.food || ExploreCategory.snack || ExploreCategory.drink => 2, _ => null },
        coordinatePrecision: 'city_area', editorialStatus: 'needs_exact_pin_review',
      ), galleryImageUrls: const [],
    );
  }
}

(String, String, String) _copy(String locale, String category, String title, String city) {
  final short = switch (locale) {
    'tr' => '$title — $city için öne çıkan ${_categoryTr[category] ?? 'keşif'} seçeneklerinden biri.',
    'de' => '$title — eine ausgewählte ${_categoryDe[category] ?? 'Entdeckung'} in $city.',
    'fr' => '$title — une sélection ${_categoryFr[category] ?? 'découverte'} à $city.',
    'es' => '$title — una selección de ${_categoryEs[category] ?? 'descubrimiento'} en $city.',
    'it' => '$title — una selezione di ${_categoryIt[category] ?? 'scoperta'} a $city.',
    'ar' => '$title — من الاختيارات البارزة في فئة ${_categoryAr[category] ?? 'الاكتشاف'} في $city.',
    _ => '$title — a flagship ${_categoryEn[category] ?? 'discovery'} in $city.',
  };
  final detail = switch (locale) {
    'tr' => '$title, $city keşif planında değerlendirebileceğin öne çıkan duraklardan biridir. Ziyaret öncesi güncel erişim, saat, fiyat ve yerel koşulları kontrol et. Harita noktası editoryal doğrulama tamamlanana kadar şehir-bölge seviyesindedir.',
    'de' => '$title gehört zu den ausgewählten Empfehlungen für $city. Prüfe vor dem Besuch Zugang, Öffnungszeiten, Preise und lokale Hinweise. Der Kartenpunkt bleibt bis zur redaktionellen Prüfung auf Stadtebene.',
    'fr' => '$title fait partie des sélections principales pour $city. Vérifiez l’accès, les horaires, les prix et les informations locales avant la visite. Le point cartographique reste approximatif jusqu’à validation éditoriale.',
    'es' => '$title forma parte de las selecciones principales de $city. Comprueba acceso, horarios, precios e información local antes de visitar. El punto del mapa es aproximado hasta la revisión editorial.',
    'it' => '$title fa parte delle selezioni principali per $city. Controlla accesso, orari, prezzi e indicazioni locali prima della visita. Il punto sulla mappa resta approssimativo fino alla verifica editoriale.',
    'ar' => '$title من الاختيارات الرئيسية في $city. تحقق من الوصول والمواعيد والأسعار والإرشادات المحلية قبل الزيارة. تبقى نقطة الخريطة تقريبية حتى اكتمال المراجعة التحريرية.',
    _ => '$title is part of the flagship discovery set for $city. Check current access, hours, pricing and local guidance before visiting. The map point remains city-area level until editorial verification is complete.',
  };
  final tip = switch (locale) {
    'tr' => 'Yoğun saatlerden kaçınmak için güncel yerel bilgiyi kontrol et.',
    'de' => 'Aktuelle lokale Hinweise prüfen, um Stoßzeiten zu vermeiden.',
    'fr' => 'Consultez les informations locales pour éviter les heures de pointe.',
    'es' => 'Consulta información local actual para evitar horas punta.',
    'it' => 'Controlla le informazioni locali per evitare gli orari di punta.',
    'ar' => 'تحقق من المعلومات المحلية لتجنب أوقات الازدحام.',
    _ => 'Check current local guidance to avoid peak times.',
  };
  return (short, detail, tip);
}

